export function Composition({
  showHeader = {{showHeader}},
  showFooter = {{showFooter}},
  layout = "{{layout}}",
  accent = "{{accent}}",
}) {
  const label = `Composed panel, layout ${layout}, header ${showHeader ? "present" : "absent"}, footer ${showFooter ? "present" : "absent"}`;
  return (
    <div role="img" aria-label={label} style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box",
      display: "flex", flexDirection: layout === "stacked" ? "column" : "row", gap: 8, border: "1.5px dashed #24143030" }}>
      {showHeader && <div style={{ padding: 14, borderRadius: 8, textAlign: "center", flex: 1, boxSizing: "border-box", background: accent, fontWeight: 600 }}>Header</div>}
      <div style={{ padding: 14, borderRadius: 8, textAlign: "center", flex: 1, boxSizing: "border-box", background: "#24143010" }}>Body</div>
      {showFooter && <div style={{ padding: 14, borderRadius: 8, textAlign: "center", flex: 1, boxSizing: "border-box", background: accent, fontWeight: 600 }}>Footer</div>}
    </div>
  );
}
